<script lang="ts">
	import { box, mergeProps } from "svelte-toolbelt";
	import type { PaneProps } from "./types.js";
	import { noop } from "../internal/helpers.js";
	import { Panpens } from "../paneforge.svelte.js";

	const uid = $props.id();

	let {
		id = uid,
		ref = $bindable(null),
		collapsedSize,
		collapsible,
		defaultSize,
		maxSize,
		minSize,
		onCollapse = noop,
		onExpand = noop,
		onResize = noop,
		order,
		child,
		children,
		...restProps
	}: PaneProps = $props();

	const panpens = Panpens.create({
		id: box.with(() => id),
		ref: box.with(
			() => ref,
			(v) => (ref = v)
		),
		collapsedSize: box.with(() => collapsedSize),
		collapsible: box.with(() => collapsible),
		defaultSize: box.with(() => defaultSize),
		maxSize: box.with(() => maxSize),
		minSize: box.with(() => minSize),
		onCollapse: box.with(() => onCollapse),
		onExpand: box.with(() => onExpand),
		onResize: box.with(() => onResize),
		order: box.with(() => order),
	});

	export const collapse = panpens.pane.collapse;
	export const expand = panpens.pane.expand;
	export const getSize = panpens.pane.getSize;
	export const isCollapsed = panpens.pane.isCollapsed;
	export const isExpanded = panpens.pane.isExpanded;
	export const resize = panpens.pane.resize;
	export const getId = panpens.pane.getId;

	const mergedProps = $derived(mergeProps(restProps, panpens.props));
</script>

{#if child}
	{@render child({ props: mergedProps })}
{:else}
	<div {...mergedProps}>
		{@render children?.()}
	</div>
{/if}
